`timescale 1ns/1ps
module tb_qwen2_projection_tile16_controller;
 localparam integer RECORDS=6188,BASE=4096;logic clk=0,rst_n=0,start;always #0.5 clk=~clk;logic[127:0]commands[0:2],records[0:RECORDS-1];logic dqv,dqr,dsv,dsr,dse;logic[23:0]dqi;logic[127:0]dsd;logic av,ar,asv,asr,ase;logic[1:0]ak;logic[63:0]as,ad;logic[31:0]ab,an,ass,ads;logic rv,rr,rsv,rsr,wv,wr,done;logic[14:0]ra,wa;logic[511:0]rd,wd;logic[63:0]be;logic[7:0]status;logic[17:0]cols;logic[5:0]tiles;logic[31:0]steps,lfsr;logic[63:0]dr,dw;logic dpending,apending,lpending;logic[127:0]dpending_data;logic[511:0]lpending_data,l2[0:8191],activation[0:1535],weights[0:73727],expected[0:767],out[0:767];integer fetches,dmas,loads,stores,delay,tile,projection,expected_columns,expected_tiles,expected_steps,expected_dmas,expected_values;logic[63:0]expected_read,expected_write,expected_macs;
 qwen2_projection_tile16_controller dut(.clk_i(clk),.rst_ni(rst_n),.start_i(start),.command_i(commands[projection]),.activation_local_i(64'h40000),.weight_local_i(64'h60000),.output_local_i(64'h78000),.descriptor_req_valid_o(dqv),.descriptor_req_ready_i(dqr),.descriptor_req_index_o(dqi),.descriptor_rsp_valid_i(dsv),.descriptor_rsp_ready_o(dsr),.descriptor_rsp_data_i(dsd),.descriptor_rsp_error_i(dse),.dma_req_valid_o(av),.dma_req_ready_i(ar),.dma_req_kind_o(ak),.dma_src_addr_o(as),.dma_dst_addr_o(ad),.dma_row_bytes_o(ab),.dma_rows_o(an),.dma_src_stride_o(ass),.dma_dst_stride_o(ads),.dma_rsp_valid_i(asv),.dma_rsp_ready_o(asr),.dma_rsp_error_i(ase),.l2_rd_valid_o(rv),.l2_rd_ready_i(rr),.l2_rd_addr_o(ra),.l2_rsp_valid_i(rsv),.l2_rsp_ready_o(rsr),.l2_rsp_data_i(rd),.l2_wr_valid_o(wv),.l2_wr_ready_i(wr),.l2_wr_addr_o(wa),.l2_wr_data_o(wd),.l2_wr_be_o(be),.done_o(done),.status_o(status),.output_columns_o(cols),.column_tiles_o(tiles),.matrix_steps_o(steps),.ddr_read_bytes_o(dr),.ddr_write_bytes_o(dw));
 assign dqr=!dpending&&(lfsr[0]||lfsr[5]);assign dsv=dpending;assign dsd=dpending_data;assign dse=0;assign ar=!apending&&(lfsr[1]||lfsr[7]);assign asv=apending&&delay==0;assign ase=0;assign rr=!lpending&&(lfsr[2]||lfsr[8]);assign rsv=lpending;assign rd=lpending_data;assign wr=lfsr[3]||lfsr[9];
 always@(posedge clk or negedge rst_n)if(!rst_n)begin lfsr<=32'h4816a11d;dpending<=0;dpending_data<=0;apending<=0;lpending<=0;lpending_data<=0;fetches<=0;dmas<=0;loads<=0;stores<=0;delay<=0;tile<=0;end else begin lfsr<={lfsr[30:0],lfsr[31]^lfsr[21]^lfsr[1]^lfsr[0]};if(dqv&&dqr)begin dpending<=1;dpending_data<=records[dqi-BASE];fetches<=fetches+1;end if(dsv&&dsr)dpending<=0;if(rv&&rr)begin lpending<=1;lpending_data<=l2[ra];end if(rsv&&rsr)lpending<=0;if(wv&&wr)l2[wa]<=wd;if(av&&ar)begin apending<=1;delay<=lfsr[12+:3];dmas<=dmas+1;if(ak==1)begin if(ab!=64||an!=1536||ass!=expected_columns*2||ads!=64||ad!=64'h60000)$fatal(1,"load request");tile=loads;for(integer k=0;k<1536;k++)l2[6144+k]=weights[k*expected_tiles+tile];loads<=loads+1;end else if(ak==3)begin if(ab!=64||an!=16||ass!=64||ads!=expected_columns*2||as!=64'h78000)$fatal(1,"store request");tile=stores;for(integer t=0;t<16;t++)out[t*expected_tiles+tile]=l2[7680+t];stores<=stores+1;end else $fatal(1,"kind=%0d",ak);end if(apending)begin if(delay!=0)delay<=delay-1;else if(asv&&asr)apending<=0;end end
 initial begin string cp,rp,kind,wp,ep;start=0;if(!$value$plusargs("COMMANDS=%s",cp)||!$value$plusargs("RECORDS=%s",rp))$fatal(1,"plusargs");if(!$value$plusargs("PROJECTION=%d",projection))projection=0;if(projection<0||projection>2)$fatal(1,"projection");kind=projection==0?"q":(projection==1?"k":"v");expected_columns=projection==0?1536:256;expected_tiles=expected_columns/32;expected_steps=expected_tiles*1536;expected_dmas=expected_tiles*2;expected_values=16*expected_columns;expected_read=64'(expected_tiles)*98304;expected_write=64'(expected_values)*2;expected_macs=64'd16*expected_columns*1536;wp=$sformatf("work/results/qwen2_canonical_q_tile16_all/%s_weight_ddr_beats.memh",kind);ep=$sformatf("work/results/qwen2_canonical_q_tile16_all/%s_expected_token_major.memh",kind);$readmemh(cp,commands);$readmemh(rp,records);$readmemh("work/results/qwen2_canonical_tile16_vectors/activation_kmajor.memh",activation);$readmemh(wp,weights);$readmemh(ep,expected);for(integer k=0;k<1536;k++)l2[4096+k]=activation[k];repeat(8)@(posedge clk);rst_n=1;@(negedge clk);start=1;@(posedge clk);@(negedge clk);start=0;wait(done);if(status||fetches!=6||dmas!=expected_dmas||loads!=expected_tiles||stores!=expected_tiles||cols!=expected_columns||tiles!=expected_tiles||steps!=expected_steps||dr!=expected_read||dw!=expected_write)$fatal(1,"aggregate status=%0d fetch=%0d dmas=%0d load=%0d store=%0d cols=%0d tiles=%0d steps=%0d bytes=%0d/%0d",status,fetches,dmas,loads,stores,cols,tiles,steps,dr,dw);for(integer i=0;i<16*expected_tiles;i++)if(out[i]!==expected[i])$fatal(1,"output beat=%0d",i);$display("QWEN2_PROJECTION_TILE16_CONTROLLER_PASS command=%s rows=16 columns=%0d tiles=%0d descriptor_fetches=6 dma_requests=%0d matrix_steps=%0d effective_macs=%0d bf16_bit_exact=%0d completion=1 random_backpressure=1",kind,expected_columns,expected_tiles,expected_dmas,expected_steps,expected_macs,expected_values);$finish;end
